templates.neutral:
flow "{{title}}" direction=down desc="{{description}}"

node client client "{{client}}" sub="Web or mobile"

group edge "Edge" type=network {
  node gateway gateway "{{gateway}}" sub="Checks sign-in"
}

group app "{{service}}" type=app-tier {
  node api service "{{api}}" sub="Takes payments"
  node worker service "{{worker}}" sub="Settles payments"
}

node queue queue "{{queue}}" sub="Settlement jobs"

group data "Data" type=data-tier {
  node db database "{{database}}" sub="Managed database"
}

node psp external "{{provider}}" sub="Card network"

client -> gateway : "POST /payments"
gateway -> api
api -> psp : "charge card"
api ..> queue : "settle later" role=async
queue ..> worker
worker -> db : "write ledger" role=data

